app.post('/api/checkins',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),g=req.user!.gym_id; const student=await one(`SELECT s.*,e.ends_on FROM students s LEFT JOIN LATERAL(SELECT ends_on FROM enrollments WHERE student_id=s.id AND gym_id=$1 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1)e ON true WHERE s.id=$2 AND s.gym_id=$1`,[g,b.student_id]); if(!student)return reply.code(404).send({error:'Aluno não encontrado'}); if(student.status!=='active')return reply.code(400).send({error:'Aluno inativo'}); if(student.ends_on && new Date(student.ends_on)<new Date())return reply.code(400).send({error:'Matrícula vencida'}); const existing=await one(`SELECT * FROM checkins WHERE gym_id=$1 AND student_id=$2 AND checked_at>=CURRENT_DATE`,[g,b.student_id]); if(existing)return {already:true,checkin:existing,student}; const c=await one(`INSERT INTO checkins(gym_id,student_id,method,confidence,created_by) VALUES($1,$2,$3,$4,$5) RETURNING *`,[g,b.student_id,b.method||'manual',b.confidence||null,req.user!.id]); return reply.code(201).send({already:false,checkin:c,student});});

app.post('/api/face/enroll',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),g=req.user!.gym_id; if(!b.student_id||!Array.isArray(b.descriptor)||b.descriptor.length<64||!b.consent)return reply.code(400).send({error:'É necessário descriptor facial e consentimento'}); const student=await one(`SELECT id FROM students WHERE id=$1 AND gym_id=$2`,[b.student_id,g]); if(!student)return reply.code(404).send({error:'Aluno não encontrado'}); const enc=encrypt(JSON.stringify(b.descriptor)); await q(`INSERT INTO face_profiles(gym_id,student_id,descriptor_encrypted,consent_at,revoked_at) VALUES($1,$2,$3,now(),NULL) ON CONFLICT(gym_id,student_id) DO UPDATE SET descriptor_encrypted=EXCLUDED.descriptor_encrypted,consent_at=now(),revoked_at=NULL,updated_at=now()`,[g,b.student_id,enc]); return {ok:true};});
app.delete('/api/face/enroll/:studentId',{preHandler:requireAuth},async(req:Req)=>{await q(`UPDATE face_profiles SET revoked_at=now(),updated_at=now() WHERE student_id=$1 AND gym_id=$2`,[(req.params as any).studentId,req.user!.gym_id]); return {ok:true};});
app.post('/api/face/match',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req); if(!Array.isArray(b.descriptor))return reply.code(400).send({error:'Descriptor inválido'}); const rows=await q(`SELECT fp.student_id,fp.descriptor_encrypted,s.full_name,s.status,e.ends_on FROM face_profiles fp JOIN students s ON s.id=fp.student_id LEFT JOIN LATERAL(SELECT ends_on FROM enrollments WHERE student_id=s.id AND gym_id=$1 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1)e ON true WHERE fp.gym_id=$1 AND fp.revoked_at IS NULL AND s.status='active'`,[req.user!.gym_id]); let best:any=null; for(const r of rows){try{const d=JSON.parse(decrypt(r.descriptor_encrypted)); if(d.length!==b.descriptor.length)continue; let sum=0; for(let i=0;i<d.length;i++){const diff=Number(d[i])-Number(b.descriptor[i]); sum+=diff*diff;} const dist=Math.sqrt(sum); if(!best||dist<best.distance)best={student_id:r.student_id,full_name:r.full_name,distance:dist,ends_on:r.ends_on};}catch{}} if(!best||best.distance>Number(b.threshold||0.52))return reply.code(404).send({error:'Rosto não reconhecido'}); return {match:best};});

app.get('/api/cash/current',{preHandler:requireAuth},async(req:Req)=>{const r=await one(`SELECT * FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1`,[req.user!.gym_id]); if(!r)return {register:null,movements:[]}; const movements=await q(`SELECT * FROM cash_movements WHERE register_id=$1 ORDER BY created_at DESC`,[r.id]); return {register:r,movements};});
const openCashRegister=async(gym:string)=>one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1`,[gym]);
const addCashMovement=async(gym:string,type:string,amount:number,method:string,description:string,reference:string|null,user:string)=>{const r=await openCashRegister(gym); if(!r)return null; const dir=['withdrawal'].includes(type)?'out':'in'; return one(`INSERT INTO cash_movements(gym_id,register_id,type,direction,amount,method,description,reference_id,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *`,[gym,r.id,type,dir,amount,method,description,reference,user]);};
const createFinancialReceipt=async(input:any)=>{const client=input.client;const runOne=async(text:string,params:any[])=>client?(await client.query(text,params)).rows[0]||null:one(text,params);const runMany=async(text:string,params:any[])=>client?(await client.query(text,params)).rows: q(text,params);const company=await runOne(`SELECT name,cnpj,address FROM gyms WHERE id=$1`,[input.gym]);const attendant=input.user?await runOne(`SELECT name FROM users WHERE id=$1 AND gym_id=$2`,[input.user,input.gym]):null;let student=input.payload?.student||null;if(!student&&(input.payment_id||input.enrollment_id||input.sale_id))student=await runOne(`SELECT s.full_name, s.cpf, s.id FROM students s WHERE s.id=COALESCE((SELECT student_id FROM payments WHERE id=$1 AND gym_id=$2),(SELECT student_id FROM enrollments WHERE id=$3 AND gym_id=$2),(SELECT student_id FROM sales WHERE id=$4 AND gym_id=$2))`,[input.payment_id||null,input.gym,input.enrollment_id||null,input.sale_id||null]);let enrollment=input.payload?.enrollment||null;if(!enrollment&&input.enrollment_id)enrollment=await runOne(`SELECT e.id,e.starts_on,e.ends_on,e.status,p.name plan_name FROM enrollments e JOIN plans p ON p.id=e.plan_id WHERE e.id=$1 AND e.gym_id=$2`,[input.enrollment_id,input.gym]);let items=input.payload?.items||null;if(!items&&input.sale_id)items=await runMany(`SELECT description,quantity,unit_price,total FROM sale_items WHERE sale_id=$1 ORDER BY id`,[input.sale_id]);const payload={...(input.payload||{}),company,attendant_name:attendant?.name||null,student,enrollment,items};return runOne(`INSERT INTO financial_receipts(gym_id,operation_type,payment_id,enrollment_id,sale_id,amount,payload,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id,receipt_number,operation_type,amount,status,created_at,payload`,[input.gym,input.operation_type,input.payment_id||null,input.enrollment_id||null,input.sale_id||null,Number(input.amount||0),JSON.stringify(payload),input.user||null]);};
app.post('/api/cash/open',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),opening=Number(b.opening_amount||0);if(!Number.isFinite(opening)||opening<0)return reply.code(400).send({error:'Informe um fundo inicial válido.'}); const open=await one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open'`,[req.user!.gym_id]); if(open)return reply.code(400).send({error:'Já existe um caixa aberto'}); const r=await one(`INSERT INTO cash_registers(gym_id,opened_by,opening_amount) VALUES($1,$2,$3) RETURNING *`,[req.user!.gym_id,req.user!.id,opening]); return reply.code(201).send(r);});
app.post('/api/cash/movement',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),amount=Number(b.amount);if(!Number.isFinite(amount)||amount<=0)return reply.code(400).send({error:'Informe um valor maior que zero.'}); const r=await one(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open'`,[req.user!.gym_id]); if(!r)return reply.code(400).send({error:'Abra o caixa antes'}); const type=b.type==='withdrawal'?'withdrawal':'supply'; const m=await one(`INSERT INTO cash_movements(gym_id,register_id,type,direction,amount,method,description,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *`,[req.user!.gym_id,r.id,type,type==='withdrawal'?'out':'in',amount,b.method||'cash',String(b.description||'').slice(0,240),req.user!.id]); return reply.code(201).send(m);});
app.post('/api/cash/close',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),r=await one(`SELECT * FROM cash_registers WHERE gym_id=$1 AND status='open'`,[req.user!.gym_id]); if(!r)return reply.code(404).send({error:'Nenhum caixa aberto'});const methods=['cash','pix','card','transfer','other'],actualByMethod:any={};for(const method of methods){const value=Number(b.closing_by_method?.[method]??0);if(!Number.isFinite(value)||value<0)return reply.code(400).send({error:'Informe valores válidos para cada forma de pagamento.'});actualByMethod[method]=money(value);}const rows=await q(`SELECT method,COALESCE(sum(CASE WHEN direction='in' THEN amount ELSE -amount END),0) total FROM cash_movements WHERE register_id=$1 AND NOT(type='supply' AND description='Fundo inicial') GROUP BY method`,[r.id]);const expectedByMethod:any={cash:money(r.opening_amount),pix:0,card:0,transfer:0,other:0};for(const row of rows)expectedByMethod[methods.includes(row.method)?row.method:'other']=money(expectedByMethod[methods.includes(row.method)?row.method:'other']+Number(row.total||0));const differenceByMethod:any={};for(const method of methods)differenceByMethod[method]=money(actualByMethod[method]-expectedByMethod[method]);const expected=money(Object.values(expectedByMethod).reduce((a:any,v:any)=>a+Number(v),0)),actual=money(Object.values(actualByMethod).reduce((a:any,v:any)=>a+Number(v),0));const closed=await one(`UPDATE cash_registers SET status='closed',closed_by=$1,closed_at=now(),closing_amount=$2,expected_amount=$3,difference=$4,closing_by_method=$5,expected_by_method=$6,difference_by_method=$7,notes=$8 WHERE id=$9 RETURNING *`,[req.user!.id,actual,expected,money(actual-expected),JSON.stringify(actualByMethod),JSON.stringify(expectedByMethod),JSON.stringify(differenceByMethod),b.notes||null,r.id]);return {register:closed,expected_by_method:expectedByMethod,closing_by_method:actualByMethod,difference_by_method:differenceByMethod};});

app.post('/api/sales',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req),items=Array.isArray(b.items)?b.items:[],method=String(b.method||'pix');if(!items.length)return reply.code(400).send({error:'Venda sem itens'});if(!['cash','pix','card','transfer','other'].includes(method))return reply.code(400).send({error:'Forma de pagamento inválida.'});const client=await pool.connect();try{await client.query('BEGIN');const register=(await client.query(`SELECT id FROM cash_registers WHERE gym_id=$1 AND status='open' ORDER BY opened_at DESC LIMIT 1 FOR UPDATE`,[req.user!.gym_id])).rows[0];if(!register)throw new Error('Abra o caixa antes de lançar uma venda.');if(b.student_id){const student=(await client.query(`SELECT id FROM students WHERE id=$1 AND gym_id=$2 AND status='active'`,[b.student_id,req.user!.gym_id])).rows[0];if(!student)throw new Error('Aluno inválido para esta venda.');}let subtotal=0;const normalized:any[]=[];for(const it of items){if(Boolean(it.product_id)===Boolean(it.service_id))throw new Error('Cada item deve ser um produto ou um serviço.');let source=null;if(it.product_id)source=(await client.query(`SELECT * FROM products WHERE id=$1 AND gym_id=$2 AND active=true FOR UPDATE`,[it.product_id,req.user!.gym_id])).rows[0];else source=(await client.query(`SELECT * FROM services WHERE id=$1 AND gym_id=$2 AND active=true`,[it.service_id,req.user!.gym_id])).rows[0];if(!source)throw new Error('Item inválido');const qty=Number(it.quantity??1),price=Number(source.price);if(!Number.isFinite(qty)||qty<=0)throw new Error(`Quantidade inválida: ${source.name}`);if(!Number.isFinite(price)||price<0)throw new Error(`Preço inválido: ${source.name}`);if(it.product_id&&Number(source.stock)<qty)throw new Error(`Estoque insuficiente: ${source.name}`);const line=money(qty*price);subtotal+=line;normalized.push({it,source,qty,price,line});}const discount=Number(b.discount||0);if(!Number.isFinite(discount)||discount<0||discount>subtotal)throw new Error('Desconto inválido. Ele não pode ser maior que o subtotal.');const total=money(subtotal-discount);const sale=(await client.query(`INSERT INTO sales(gym_id,student_id,total,discount,method,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *`,[req.user!.gym_id,b.student_id||null,total,discount,method,req.user!.id])).rows[0];for(const n of normalized){await client.query(`INSERT INTO sale_items(sale_id,product_id,service_id,description,quantity,unit_price,total) VALUES($1,$2,$3,$4,$5,$6,$7)`,[sale.id,n.it.product_id||null,n.it.service_id||null,n.source.name,n.qty,n.price,n.line]);if(n.it.product_id)await client.query(`UPDATE products SET stock=stock-$1,updated_at=now() WHERE id=$2 AND gym_id=$3`,[n.qty,n.it.product_id,req.user!.gym_id]);}await client.query(`INSERT INTO cash_movements(gym_id,register_id,type,direction,amount,method,description,reference_id,created_by) VALUES($1,$2,'sale','in',$3,$4,'Venda',$5,$6)`,[req.user!.gym_id,register.id,total,method,sale.id,req.user!.id]);const receipt=await createFinancialReceipt({client,gym:req.user!.gym_id,operation_type:'sale',sale_id:sale.id,amount:total,payload:{title:'COMPROVANTE DE VENDA',student_id:b.student_id||null,items:normalized.map((n:any)=>({description:n.source.name,quantity:n.qty,unit_price:n.price,total:n.line})),discount,method:method,status:'paid'},user:req.user!.id});await client.query('COMMIT');return reply.code(201).send({...sale,receipt});}catch(e:any){await client.query('ROLLBACK').catch(()=>{});return reply.code(400).send({error:e.message||'Não foi possível concluir a venda'});}finally{client.release();}});
app.get('/api/sales',{preHandler:requireAuth},async(req:Req)=>q(`SELECT s.*,st.full_name student_name,(SELECT json_agg(si) FROM sale_items si WHERE si.sale_id=s.id) items FROM sales s LEFT JOIN students st ON st.id=s.student_id WHERE s.gym_id=$1 ORDER BY s.sold_at DESC LIMIT 300`,[req.user!.gym_id]));
app.get('/api/finance/ledger',{preHandler:requireAuth},async(req:Req)=>{const g=req.user!.gym_id;const [ledger,cashRegisters]=await Promise.all([q(`SELECT * FROM (SELECT * FROM (${FINANCIAL_OPERATIONS_SQL}) operations UNION ALL SELECT * FROM (${STANDALONE_CASH_SQL}) cash) ledger ORDER BY COALESCE(occurred_at,created_at) DESC LIMIT 500`,[g]),q(`SELECT cr.*,ou.name opened_by_name,cu.name closed_by_name,COALESCE(SUM(CASE WHEN cm.direction='in' AND NOT(cm.type='supply' AND cm.description='Fundo inicial') THEN cm.amount ELSE 0 END),0) total_in,COALESCE(SUM(CASE WHEN cm.direction='out' THEN cm.amount ELSE 0 END),0) total_out,COUNT(cm.id)::int movement_count FROM cash_registers cr LEFT JOIN users ou ON ou.id=cr.opened_by LEFT JOIN users cu ON cu.id=cr.closed_by LEFT JOIN cash_movements cm ON cm.register_id=cr.id WHERE cr.gym_id=$1 GROUP BY cr.id,ou.name,cu.name ORDER BY cr.opened_at DESC LIMIT 100`,[g])]);const openCount=cashRegisters.filter((x:any)=>x.status==='open').length;return {ledger,cashRegisters,summary:{open_count:openCount,closed_count:cashRegisters.length-openCount,open_balance:cashRegisters.filter((x:any)=>x.status==='open').reduce((a:any,x:any)=>a+Number(x.opening_amount||0)+Number(x.total_in||0)-Number(x.total_out||0),0),closed_total_in:cashRegisters.filter((x:any)=>x.status==='closed').reduce((a:any,x:any)=>a+Number(x.total_in||0),0),closed_total_out:cashRegisters.filter((x:any)=>x.status==='closed').reduce((a:any,x:any)=>a+Number(x.total_out||0),0)}}});
app.get('/api/receipts/:id',{preHandler:requireAuth},async(req:Req,reply)=>{const r=await one(`SELECT * FROM financial_receipts WHERE id=$1 AND gym_id=$2`,[(req.params as any).id,req.user!.gym_id]);return r||reply.code(404).send({error:'Comprovante não encontrado'});});

app.get('/api/team',{preHandler:requireAuth},async(req:Req)=>q(`SELECT id,name,email,role,status,last_login_at,created_at FROM users WHERE gym_id=$1 ORDER BY name`,[req.user!.gym_id]));
app.post('/api/team',{preHandler:requireAuth},async(req:Req,reply)=>{if(!['admin','manager'].includes(req.user!.role))return reply.code(403).send({error:'Sem permissão'}); const b=body(req); if(!b.name||!b.email||!b.password)return reply.code(400).send({error:'Nome, e-mail e senha são obrigatórios'}); try{const h=await argon2.hash(b.password); const u=await one(`INSERT INTO users(gym_id,name,email,password_hash,role) VALUES($1,$2,$3,$4,$5) RETURNING id,name,email,role,status`,[req.user!.gym_id,b.name,b.email.toLowerCase(),h,b.role||'reception']);return reply.code(201).send(u);}catch{return reply.code(400).send({error:'E-mail já cadastrado'});}});

app.get('/api/reports/overview',{preHandler:requireAuth},async(req:Req)=>{const g=req.user!.gym_id;const [monthly,plans,methods,attendance]=await Promise.all([q(`SELECT to_char(date_trunc('month',occurred_at),'YYYY-MM') AS "month",COALESCE(sum(amount) FILTER(WHERE status='paid'),0) revenue,COALESCE(sum(amount) FILTER(WHERE status='pending' AND operation='payment'),0) pending FROM (${FINANCIAL_OPERATIONS_SQL}) operations WHERE occurred_at>=now()-interval '12 months' GROUP BY 1 ORDER BY 1`,[g]),q(`SELECT pl.name,count(DISTINCT e.id)::int enrollments,COALESCE(sum(p.amount) FILTER(WHERE p.status='paid'),0) revenue FROM enrollments e JOIN plans pl ON pl.id=e.plan_id LEFT JOIN payments p ON p.enrollment_id=e.id AND p.gym_id=e.gym_id WHERE e.gym_id=$1 GROUP BY pl.name ORDER BY revenue DESC`,[g]),q(`SELECT method,count(*)::int count,COALESCE(sum(amount),0) total FROM (${FINANCIAL_OPERATIONS_SQL}) operations WHERE status='paid' GROUP BY method ORDER BY total DESC`,[g]),q(`SELECT to_char(date_trunc('day',checked_at),'YYYY-MM-DD') AS "day",count(*)::int checkins FROM checkins WHERE gym_id=$1 AND checked_at>=now()-interval '30 days' GROUP BY 1 ORDER BY 1`,[g])]);return {monthly,plans,methods,attendance};});
